'use strict';
const LEAGUES=[['tur.1','Süper Lig','🇹🇷'],['eng.1','Premier League','🏴'],['esp.1','La Liga','🇪🇸'],['ger.1','Bundesliga','🇩🇪'],['ita.1','Serie A','🇮🇹'],['fra.1','Ligue 1','🇫🇷'],['uefa.champions','Şampiyonlar Ligi','🏆'],['uefa.europa','Avrupa Ligi','🏅'],['uefa.europa.conf','Konferans Ligi','🥇'],['ned.1','Eredivisie','🇳🇱'],['eng.2','Championship','🏴'],['fifa.world','Dünya Kupası','🌍'],['uefa.euro','Avrupa Şampiyonası','🇪🇺'],['uefa.nations','Uluslar Ligi','🌍'],['conmebol.america','Copa América','🌎'],['concacaf.gold.cup','Gold Cup','🌎'],['afc.asian.cup','Asya Kupası','🌏'],['caf.nations','Afrika Uluslar Kupası','🌍']];
const BASE='https://site.api.espn.com/apis/site/v2/sports/soccer/';const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const key='map-v3-';const FINISHED_WINDOW=2*60*60*1000;const finishedTimes=read('finishedTimes',{});function finishedAt(m,now=Date.now()){if(!m.done)return null;const kickoff=Date.parse(m.date);if(!Number.isFinite(kickoff)||kickoff>now||now-kickoff>6*60*60*1000)return null;return Number(finishedTimes[m.id])||kickoff+2*60*60*1000}function retainFinished(m,now=Date.now()){const end=finishedAt(m,now);return m.done&&end!==null&&now>=end&&now-end<FINISHED_WINDOW}function recordFinished(m,now=Date.now()){if(!finishedTimes[m.id]){finishedTimes[m.id]=now;save('finishedTimes',finishedTimes)}}const state={archive:[],modelComparison:null,page:'home',league:'all',match:null,market:'all',listGroup:'all',listMarket:'all',accuracyFilter:'result',slide:0,fixtures:[],failures:[],loading:false,settings:read('settings',{auto:true}),favs:read('favorites',[]),updated:read('updated',0),playerFeatures:read('playerFeatures',null)};
function read(k,fallback){try{return JSON.parse(localStorage.getItem(key+k))??fallback}catch{return fallback}}function save(k,v){try{localStorage.setItem(key+k,JSON.stringify(v))}catch{}}const fmt=d=>new Date(d).toLocaleString('tr-TR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});const dateKey=d=>{let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}${m}${day}`};
function parseEvent(e,league){const c=e.competitions?.[0],h=c?.competitors?.find(t=>t.homeAway==='home'),a=c?.competitors?.find(t=>t.homeAway==='away');if(!h||!a)return null;let done=e.status?.type?.completed===true;return {id:league+':'+e.id,league,date:e.date,done,home:{id:String(h.team?.id),name:h.team?.displayName||h.team?.name||'Ev sahibi',logo:h.team?.logo||h.team?.logos?.[0]?.href||'',score:done?Number(h.score):null},away:{id:String(a.team?.id),name:a.team?.displayName||a.team?.name||'Deplasman',logo:a.team?.logo||a.team?.logos?.[0]?.href||'',score:done?Number(a.score):null}}}
async function fetchLeague(code){let now=new Date(),start=new Date(now),end=new Date(now);start.setDate(start.getDate()-120);end.setDate(end.getDate()+14);let url=BASE+encodeURIComponent(code)+'/scoreboard?dates='+dateKey(start)+'-'+dateKey(end)+'&limit=1000';let ctl=new AbortController(),timeout=setTimeout(()=>ctl.abort(),16000);try{let r=await fetch(url,{signal:ctl.signal});if(!r.ok)throw Error('HTTP '+r.status);let j=await r.json();let ev=(j.events||[]).map(e=>parseEvent(e,code)).filter(Boolean);if(!ev.length)throw Error('Boş veri');return ev}finally{clearTimeout(timeout)}}
function history(team,date,all){return all.filter(m=>m.done&&new Date(m.date)<new Date(date)&&(m.home.id===team.id||m.away.id===team.id)).sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,10)}
function form(ms,name){let w=0,d=0,l=0,gf=0,ga=0;for(let m of ms){let home=m.home.name===name,x=home?m.home.score:m.away.score,y=home?m.away.score:m.home.score;if(!Number.isFinite(x)||!Number.isFinite(y))continue;gf+=x;ga+=y;if(x>y)w++;else if(x===y)d++;else l++}return {w,d,l,gf:gf/ms.length,ga:ga/ms.length,n:ms.length}}
function pois(k,l){let x=Math.exp(-l);for(let i=1;i<=k;i++)x*=l/i;return x}
function model(m,all){let h=history(m.home,m.date,all),a=history(m.away,m.date,all);if(h.length<5||a.length<5)return {ready:false,nh:h.length,na:a.length};let hf=form(h,m.home.name),af=form(a,m.away.name),lh=Math.min(4.5,Math.max(.15,(hf.gf+af.ga)/2*1.12)),la=Math.min(4.5,Math.max(.15,(af.gf+hf.ga)/2*.9));let p={home:0,draw:0,away:0,over15:0,over25:0,over35:0,under15:0,under25:0,under35:0,btts:0,noBtts:0,homeOrDraw:0,awayOrDraw:0,noDraw:0,homeHalf:0,drawHalf:0,awayHalf:0,homeOver05:0,awayOver05:0,homeUnder15:0,awayUnder15:0,even:0,odd:0};let total=0;for(let i=0;i<=15;i++)for(let j=0;j<=15;j++){let v=pois(i,lh)*pois(j,la),g=i+j;total+=v;p[i>j?'home':i===j?'draw':'away']+=v;p[g>1?'over15':'under15']+=v;p[g>2?'over25':'under25']+=v;p[g>3?'over35':'under35']+=v;p[i&&j?'btts':'noBtts']+=v;p[i>=1?'homeOver05':'homeUnder15']+=0; // separate below
p[g%2?'odd':'even']+=v;if(i>0)p.homeOver05+=v;if(j>0)p.awayOver05+=v;if(i<2)p.homeUnder15+=v;if(j<2)p.awayUnder15+=v}
for(let k in p)p[k]/=total;p.homeOrDraw=p.home+p.draw;p.awayOrDraw=p.away+p.draw;p.noDraw=p.home+p.away;return {ready:true,p,lh,la,hf,af,nh:h.length,na:a.length}}
const markets=[['Maç Sonucu',[['1','home'],['X','draw'],['2','away']]],['Çifte Şans',[['1X','homeOrDraw'],['12','noDraw'],['X2','awayOrDraw']]],['Toplam Gol',[['0.5 Üst','over05'],['0.5 Alt','under05'],['1.5 Üst','over15'],['1.5 Alt','under15'],['2.5 Üst','over25'],['2.5 Alt','under25'],['3.5 Üst','over35'],['3.5 Alt','under35'],['4.5 Üst','over45'],['4.5 Alt','under45'],['5.5 Üst','over55'],['5.5 Alt','under55']]],['Karşılıklı Gol',[['Var','btts'],['Yok','noBtts']]],['Takım Golü',[['Ev sahibi 0.5 Üst','homeOver05'],['Ev sahibi 0.5 Alt','homeUnder05'],['Deplasman 0.5 Üst','awayOver05'],['Deplasman 0.5 Alt','awayUnder05'],['Ev sahibi 1.5 Üst','homeOver15'],['Ev sahibi 1.5 Alt','homeUnder15'],['Deplasman 1.5 Üst','awayOver15'],['Deplasman 1.5 Alt','awayUnder15'],['Ev sahibi 2.5 Üst','homeOver25'],['Ev sahibi 2.5 Alt','homeUnder25'],['Deplasman 2.5 Üst','awayOver25'],['Deplasman 2.5 Alt','awayUnder25']]],['Toplam Gol Tek/Çift',[['Tek','odd'],['Çift','even']]],['Gol Aralığı',[['0–1 Gol','goals01'],['2–3 Gol','goals23'],['4–5 Gol','goals45'],['6+ Gol','goals6plus']]],['Gol Farkı',[['Ev 1 farkla','marginHome1'],['Ev 2 farkla','marginHome2'],['Ev 3+ farkla','marginHome3plus'],['Dep 1 farkla','marginAway1'],['Dep 2 farkla','marginAway2'],['Dep 3+ farkla','marginAway3plus']]],['Kombine',[['1 ve 1.5 Üst','homeOver15Win'],['1 ve 2.5 Üst','homeOver25Win'],['2 ve 1.5 Üst','awayOver15Win'],['2 ve 2.5 Üst','awayOver25Win'],['1 ve KG Var','homeWinBtts'],['2 ve KG Var','awayWinBtts'],['2.5 Üst ve KG Var','over25Btts'],['2.5 Alt ve KG Var','under25Btts']]]];
// v30: new options are computed server-side from the same Elo-adjusted score matrix.
// Historical frozen predictions without these keys remain unchanged.
function percent(x){return Math.round(100*x)}function leagueName(code){return LEAGUES.find(x=>x[0]===code)?.[1]||code}function logo(t){return t.logo?`<img class="logo" src="${esc(t.logo)}" alt="" loading="lazy" onerror="this.style.visibility='hidden'">`:'<span class="logo">⚽</span>'}
function filtered(){return state.fixtures.filter(m=>(!m.done||retainFinished(m))&&(state.league==='all'||m.league===state.league))}function fixture(m){let data=state.history||[],an=model(m,data);return {...m,analysis:an}}function available(){return filtered().map(fixture).filter(m=>m.analysis?.ready&&m.analysis.nh>=10&&m.analysis.na>=10)}function best(m){let a=m.analysis;if(!a.ready)return null;let pairs=markets.flatMap(([group,rows])=>rows.map(([name,k])=>({group,name,k,p:a.p[k]}))).filter(x=>Number.isFinite(x.p)&&x.p>=.5);return pairs.sort((a,b)=>b.p-a.p)[0]||null}
function triple(a){return `<div class="triple"><div class="pill win">1<strong>%${percent(a.p.home)}</strong></div><div class="pill draw">X<strong>%${percent(a.p.draw)}</strong></div><div class="pill loss">2<strong>%${percent(a.p.away)}</strong></div></div>`}
function hero(m,index,total){let b=best(m),ready=m.analysis.ready;return `<div class="hero" style="background-image:linear-gradient(180deg,rgba(4,17,38,.74) 0%,rgba(5,19,39,.52) 40%,rgba(4,17,34,.84) 100%),url('./stadium-featured.webp');background-size:cover;background-position:center;background-repeat:no-repeat;" id="featured-slide" data-open="${esc(m.id)}" role="button" tabindex="0" aria-label="Öne çıkan maç ${index+1} / ${total}"><div class="top"><span class="tag">★ ${b?'Günün maçı':'Günün karşılaşması'}</span><span class="flag">${esc(leagueName(m.league))}</span></div><div class="versus"><div>${logo(m.home)}<b>${esc(m.home.name)}</b></div><strong>${(m.live||m.done)&&Number.isInteger(m.home.score)&&Number.isInteger(m.away.score)?m.home.score+' - '+m.away.score:'VS'}</strong><div>${logo(m.away)}<b>${esc(m.away.name)}</b></div></div><div class="muted" style="text-align:center;margin-bottom:10px">${m.live?`<span style="color:#ff666e;font-weight:800">🔴 CANLI ${esc(m.clock||'')}</span> · ${fmt(m.date)}`:fmt(m.date)}</div><div style="font-size:clamp(22px,4.5vw,30px);font-weight:850;text-align:center;color:#f5f9ff;margin:18px 0 14px;letter-spacing:-.4px">Maç Sonucu Tahmini <span style="white-space:nowrap;color:#b7d8ff">(1-X-2)</span></div>${ready?triple(m.analysis):'<div class="muted" style="text-align:center">Bu maç için yeterli geçmiş veri yok.</div>'}${b?`<div style="margin-top:18px;padding:13px 16px;border:1px solid #315572;border-radius:14px;background:rgba(15,36,59,.65);font-size:16px;line-height:1.55;text-align:center"><span style="color:#b6cbe0">Diğer güçlü tahmin</span><div style="font-weight:750;color:#fff">${esc(b.group)} · ${esc(b.name)} — <span style="color:#ffc847">%${percent(b.p)}</span></div></div>`:''}<div class="dots slider-dots" aria-label="${index+1}. maç, toplam ${total} maç">${Array.from({length:total},(_,i)=>`<span class="slider-dot ${i===index?'active':''}" aria-hidden="true"></span>`).join('')}</div></div>`}
function istanbulDay(date){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(date))}
function featuredMatches(){
  const now=Date.now(), today=istanbulDay(now);
  const matches=available().filter(m=>!m.done||retainFinished(m));
  // A live fixture must remain featured even after its scheduled kickoff time.
  const liveToday=matches.filter(m=>(m.live||m.done)&&istanbulDay(m.date)===today).sort((a,b)=>new Date(a.date)-new Date(b.date));
  const upcoming=matches.filter(m=>!m.live&&new Date(m.date).getTime()>=now).sort((a,b)=>new Date(a.date)-new Date(b.date));
  const todayUpcoming=upcoming.filter(m=>istanbulDay(m.date)===today);
  // Keep every live game in the carousel; show today's upcoming games alongside them.
  if(liveToday.length)return [...liveToday,...todayUpcoming];
  if(todayUpcoming.length)return todayUpcoming;
  if(!upcoming.length)return [];
  const day=istanbulDay(upcoming[0].date);
  return upcoming.filter(m=>istanbulDay(m.date)===day);
}
function liveMinute(m){let v=String(m.clock||'').match(/\d+/);return v?Math.min(120,Number(v[0])):null}
function liveAnalysis(m){const base=state.analyses?.[m.id];return base||{ready:false,nh:0,na:0};}

function matchCard(m){let a=m.analysis;return `<button class="card match" data-open="${esc(m.id)}">${logo(m.home)}<div class="teams"><small>${esc(leagueName(m.league))} · ${m.done?'✓ TAMAMLANDI':m.live?'🔴 CANLI '+esc(m.clock||''):fmt(m.date)}</small><b>${esc(m.home.name)} – ${esc(m.away.name)}${(m.live||m.done)&&Number.isInteger(m.home.score)&&Number.isInteger(m.away.score)?' · '+m.home.score+'-'+m.away.score:''}</b></div>${a.ready?`<div class="mini"><span>%${percent(a.p.home)}</span><span>%${percent(a.p.draw)}</span><span>%${percent(a.p.away)}</span></div>`:'<span class="muted">Veri az</span>'}<span>›</span></button>`}
function leagueTabs(){return `<div class="tabs"><button data-league="all" class="${state.league==='all'?'active':''}">Tümü</button>${LEAGUES.map(([id,name,flag])=>`<button data-league="${id}" class="${state.league===id?'active':''}">${flag} ${esc(name)}</button>`).join('')}</div>`}
function matchDateLabel(date){return new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'long',weekday:'long'}).format(new Date(date))}
function groupedMatchCards(items){
  // Share the home-page date headings across all match and league lists.
  // Do not mutate the source array: it is also used by live-score updates.
  const chronologically=[...items].sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));
  let previous=null;
  return chronologically.map(m=>{
    const day=istanbulDay(m.date);
    const header=day!==previous?`<div class="match-date-heading">${esc(matchDateLabel(m.date))}</div>`:'';
    previous=day;
    return header+matchCard(m);
  }).join('');
}
function home(){let all=available(),featured=featuredMatches(),idx=featured.length?((state.slide%featured.length)+featured.length)%featured.length:0;return `${leagueTabs()}${accuracyCard()}<div class="sectionhead"><h2>🏆 ${featured.length&&istanbulDay(featured[0].date)!==istanbulDay(Date.now())?'Sıradaki Günün Maçları':'Günün Öne Çıkanları'}</h2><button class="link" data-page="matches">Tümünü gör ›</button></div>${featured.length?hero(featured[idx],idx,featured.length):`<div class="empty">${state.loading?'Maç verileri alınıyor…':'Son 10 maç verisi yeterli olan yaklaşan karşılaşma bulunamadı.'}</div>`}<div class="sectionhead"><h2>Canlı ve Yaklaşan Maçlar</h2><button class="link" data-page="matches">Tümünü gör ›</button></div>${all.length?groupedMatchCards(all.slice(0,8).sort((a,b)=>new Date(a.date)-new Date(b.date))):'<div class="empty">Bu ligde henüz maç bulunamadı.</div>'}`}

function filteredMarketCard(m,marketKey,marketLabel){
  const p=m.analysis?.p?.[marketKey];
  return `<button class="card match" data-open="${esc(m.id)}">${logo(m.home)}<div class="teams"><small>${esc(leagueName(m.league))} · ${m.live?'🔴 CANLI · ':''}${fmt(m.date)}</small><b>${esc(m.home.name)} – ${esc(m.away.name)}</b><small class="market-card-label">${esc(marketLabel)}</small></div><strong class="market-card-prob">%${percent(p)}</strong><span>›</span></button>`;
}
function matches(){
  const all=available().sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));
  const title=state.league==='all'?'Tüm Maçlar':`${leagueName(state.league)} Maçları`;
  const groups=[['all','Tüm bahis türleri'],...markets.map(([name])=>[name,name])];
  const group=groups.some(([key])=>key===state.listGroup)?state.listGroup:'all';
  const options=markets.filter(([name])=>name===group).flatMap(([,rows])=>rows);
  const selected=options.some(([,key])=>key===state.listMarket)?state.listMarket:'all';
  const filterUI=`<div class="market-filter"><label for="match-filter-group">Bahis türü</label><select id="match-filter-group" aria-label="Bahis türü">${groups.map(([key,name])=>`<option value="${esc(key)}" ${group===key?'selected':''}>${esc(name)}</option>`).join('')}</select>${group!=='all'?`<label for="match-filter-choice">Tahmin seçimi</label><select id="match-filter-choice" aria-label="Tahmin seçimi"><option value="all" ${selected==='all'?'selected':''}>En güçlü seçenek (bu türde)</option>${options.map(([name,key])=>`<option value="${esc(key)}" ${selected===key?'selected':''}>${esc(name)}</option>`).join('')}</select>`:''}</div>`;
  if(group==='all')return `<h1 class="heading">${esc(title)}</h1>${leagueTabs()}${filterUI}<div class="muted">Tarihe göre sıralı · ${all.length} karşılaşma</div>${all.length?groupedMatchCards(all):'<div class="empty">Seçilen lig için maç bulunamadı.</div>'}`;
  const ranked=all.map(m=>{
    const choices=options.filter(([,key])=>selected==='all'||key===selected).map(([name,key])=>({name,key,p:m.analysis?.p?.[key]})).filter(x=>Number.isFinite(x.p));
    const best=choices.sort((a,b)=>b.p-a.p)[0];
    return best?{m,best}:null;
  }).filter(Boolean).sort((a,b)=>b.best.p-a.best.p||Date.parse(a.m.date)-Date.parse(b.m.date));
  return `<h1 class="heading">${esc(title)}</h1>${leagueTabs()}${filterUI}<div class="muted">En yüksek olasılıktan düşüğe sıralı · ${ranked.length} karşılaşma · Model tahminidir, bahis oranı değildir.</div>${ranked.length?ranked.map(({m,best})=>filteredMarketCard(m,best.key,best.name)).join(''):'<div class="empty">Bu seçim için hesaplanmış olasılık bulunamadı.</div>'}`;
}
function leagues(){return `<h1 class="heading">Ligler</h1><div class="leaguegrid">${LEAGUES.map(([id,name,flag])=>`<button data-leaguepage="${id}"><span>${flag}</span>${esc(name)}</button>`).join('')}</div>`}
function marketRow(m,group,name,k,p){let id=m.id+'|'+k,saved=state.favs.some(x=>x.id===id);return `<div class="marketrow"><div><b>${esc(name)}</b><div class="muted">${esc(group)}</div></div><span class="pct">%${percent(p)}</span><button class="star ${saved?'saved':''}" data-fav="${esc(id)}" aria-label="Favorilere ekle">${saved?'★':'☆'}</button></div>`}
function explainModel(m,a){
  if(!a?.ready)return '';
  const elo=a.elo||{}, n=Math.min(a.nh||0,a.na||0), e=Math.min(elo.homeMatches||0,elo.awayMatches||0);
  const quality=n>=10&&e>=20?'Orta — sınırlı tarihsel örneklem':'Düşük — sınırlı tarihsel örneklem';
  const fmtE=v=>Number.isFinite(Number(v))?Number(v).toFixed(1):'Veri yok';
  const adj=a.opponentAdjustment||{};
  const opponentNote=adj.home&&adj.away?`<p class="muted">Son rakiplerin ortalama Elo gücü: ${esc(m.home.name)} ${fmtE(adj.home.avgOpponentElo)}, ${esc(m.away.name)} ${fmtE(adj.away.avgOpponentElo)}. Rakip kalitesi düzeltmesi: ×${fmtE(adj.home.factor)} / ×${fmtE(adj.away.factor)}. Katsayılar temkinli ve henüz doğrulanmamıştır.</p>`:'';
  return `<section class="market" style="padding:18px;margin-top:20px"><h3>Analiz nasıl hesaplandı?</h3>
    <p class="muted">Model: ${esc(a.model||'Bilinmiyor')} · Veri değerlendirmesi: <strong>${esc(quality)}</strong></p>
    <div class="stats"><div><small>${esc(m.home.name)} · Elo</small><b>${fmtE(elo.home)}</b><small>${elo.homeMatches||0} kayıtlı maç</small></div><div><small>${esc(m.away.name)} · Elo</small><b>${fmtE(elo.away)}</b><small>${elo.awayMatches||0} kayıtlı maç</small></div></div>
    <p class="muted">Elo farkı: ${fmtE(Number(elo.home)-Number(elo.away))} · İç saha avantajı: ${fmtE(elo.homeAdvantage)} Elo puanı. Bunlar yalnızca kayıtlı maçlardan hesaplanır; tüm liglerde mutlak güç sıralaması değildir.</p>
    <div class="stats"><div><small>Ev sahibi beklenen gol</small><b>${fmtE(a.lh)}</b><small>Poisson λ</small></div><div><small>Deplasman beklenen gol</small><b>${fmtE(a.la)}</b><small>Poisson λ</small></div></div>
    <p class="muted">Son maç formu: ${esc(m.home.name)} ${a.hf.w}G ${a.hf.d}B ${a.hf.l}M; ${esc(m.away.name)} ${a.af.w}G ${a.af.d}B ${a.af.l}M. Gol ortalamaları, iç saha etkisi ve sınırlı Elo düzeltmesi birlikte kullanılır.</p>
    ${opponentNote}
    <p class="note">Eksik girdiler: doğrulanmış ilk 11, oyuncu gücü, sakatlıklar, cezalar ve xG. Bu veriler hesaplanmış gibi gösterilmez. Yüzdeler kalibre edilmiş veya bahis getirisi kanıtlanmış olasılıklar değildir.</p></section>`;
}
function playerStatsSummary(a){if(!a?.playerFeatures)return '';const side=(name,x)=>{const absent=x.unavailablePlayers?.length?x.unavailablePlayers.slice(0,3).map(esc).join(', '):'yok';const doubtful=x.doubtfulPlayers?.length?x.doubtfulPlayers.slice(0,3).map(esc).join(', '):'yok';return `<div><small>${esc(name)}</small><b>${x.goals} gol · ${x.onTarget} isabetli şut</b><small>${x.shots} şut · ${x.apps.toFixed(1)} kullanılabilir oyuncu-maçı · %${Math.round(x.coverage*100)} istatistik kapsamı</small><small>Uygunluk bildirimi: %${Math.round(x.availabilityCoverage*100)} · Oynamayacağı bildirilen: ${absent} · Şüpheli: ${doubtful}</small></div>`};return `<section class="stats player-stats">${side('Ev sahibi oyuncuları',a.playerFeatures.home)}${side('Deplasman oyuncuları',a.playerFeatures.away)}</section><p class="muted">Yalnızca maçtan önce kaydedilmiş açık uygunluk durumları kullanılır. Bilinmeyen durum nötr tutulur; bu veri kesin ilk 11 bilgisi değildir. Sakat/cezalı oyuncuların sezon katkısı bu deneysel hesapta sıfırlanır, şüpheliler yarım ağırlık alır.</p>`}
function detail(){let m=state.fixtures.find(x=>x.id===state.match)||state.history.find(x=>x.id===state.match);if(!m)return '<div class="empty">Maç bulunamadı.</div>';m=fixture(m);let a=m.analysis;return `<button class="link" data-page="matches">‹ Maçlara dön</button><h1 class="heading">Maç Detayı</h1><div class="detailhero"><div class="muted" style="text-align:center">${esc(leagueName(m.league))} · ${m.done?'✓ TAMAMLANDI':m.live?'🔴 CANLI '+esc(m.clock||''):fmt(m.date)}</div><div class="versus"><div>${logo(m.home)}<b>${esc(m.home.name)}</b></div><strong>${(m.live||m.done)&&Number.isInteger(m.home.score)&&Number.isInteger(m.away.score)?m.home.score+' - '+m.away.score:'VS'}</strong><div>${logo(m.away)}<b>${esc(m.away.name)}</b></div></div>${a.ready?triple(a):''}${a.playerModel?`<p class="muted">Oyuncu verisi dahil edilmiş deneysel tahmin · beklenen gol: ${a.playerLambda.home.toFixed(2)} – ${a.playerLambda.away.toFixed(2)}</p>${playerStatsSummary(a)}`:''}${m.live?'<p class="muted">🔴 Canlı skor. Tahminler maç öncesinde kaydedilen yüzdelerdir; maç boyunca değiştirilmez.</p>':''}</div>${!a.ready?`<div class="banner">${a.playerMLUnavailable?'Bu maç için oyuncu verili ML tahminini oluşturacak kayıtlı ML olasılığı yok.':a.playerUnavailable?'Maç başlangıcından önce alınmış yeterli oyuncu istatistiği yok; oyuncu verili olasılık gösterilmiyor.':`Güvenilir analiz için en az 5 geçmiş maç gerekli. Bulunan: ${a.nh} / ${a.na}. Olasılık gösterilmiyor.`}</div>`:a.playerModel?'<div class="banner">Oyuncu motorları şu anda yalnızca 1-X-2 maç sonucu tahmini üretir. Diğer pazarlar bu motorlara aitmiş gibi gösterilmez.</div>':`<div class="sectionhead"><h2>Maç Sonucu Tahmini (1-X-2)</h2><span class="muted">Tüm ihtimaller</span></div><section class="market"><h3>Maç Sonucu</h3>${markets[0][1].map(([name,k])=>marketRow(m,'Maç Sonucu',name,k,a.p[k])).join('')}</section><div class="sectionhead"><h2>${m.live?'Maç öncesi diğer tahminler':'Diğer bahis türü olasılıkları'}</h2><span class="muted">Bulunan tüm model olasılıkları</span></div><div class="chips">${[['all','Tümü'],...markets.slice(1).map(([n])=>[n,n])].map(([k,n])=>`<button data-market="${esc(k)}" class="${state.market===k?'active':''}">${esc(n)}</button>`).join('')}</div>${markets.slice(1).filter(([group])=>(state.market==='all'||group===state.market)).map(([group,rows])=>{let visible=rows.filter(([,k])=>Number.isFinite(a.p[k]));return visible.length?`<section class="market"><h3>${esc(group)}</h3>${visible.map(([name,k])=>marketRow(m,group,name,k,a.p[k])).join('')}</section>`:''}).join('')}<div class="banner">Şut, kaleyi bulan şut ve korner olasılıkları için yeterli geçmiş istatistik verisi bulunmadığından bu pazarlar henüz hesaplanmıyor.</div><h2 class="sectionhead">Son 10 Maç Formu (Tüm Kulvarlar)</h2><div class="stats"><div><small>${esc(m.home.name)}</small><b>${a.hf.w}G ${a.hf.d}B ${a.hf.l}M</b><small>Gol ort. ${a.hf.gf.toFixed(2)}</small></div><div><small>${esc(m.away.name)}</small><b>${a.af.w}G ${a.af.d}B ${a.af.l}M</b><small>Gol ort. ${a.af.gf.toFixed(2)}</small></div></div><p class="muted">Lig, UEFA ve veri kaynağında bulunan kupa maçları birlikte değerlendirilir. Elo takım gücü rakip seviyesine göre hesaplanır. Beklenen gol: ${a.lh.toFixed(2)} – ${a.la.toFixed(2)}. Her takım için bulunan geçmiş maç sayısı: ${a.nh} / ${a.na}.</p>${explainModel(m,a)}`}`}
function favorites(){let items=state.favs;return `<h1 class="heading">★ Favorilerim <span class="muted">(${items.length})</span></h1><p class="muted">Kaydettiğin maç ve tahminleri burada topluca görebilirsin. Yüzdeler son veri güncellemesindeki hesaplamaya göre değişebilir.</p>${items.length?items.map(f=>{let m=state.fixtures.find(x=>x.id===f.matchId);let a=m?fixture(m).analysis:null;let p=a?.ready&&Number.isFinite(a.p[f.market])?a.p[f.market]:f.p;return `<div class="card rowline"><div><b>${esc(f.home)} – ${esc(f.away)}</b><div class="muted">${esc(f.group)} · ${esc(f.name)}</div><small class="muted">${fmt(f.date)}</small></div><span class="pct" style="color:#70f4b5;font-weight:800">%${percent(p)}</span><button class="star saved" data-fav="${esc(f.id)}">★</button></div>`}).join(''):'<div class="empty">Henüz favorin yok. Maç detayında %50 üzerindeki bir tahminin yanındaki ☆ simgesine dokun.</div>'}`}
function modelComparisonCard(){const c=state.modelComparison||{},models=c.models||{},n=c.evaluatedMatches||0;const value=x=>x?.hitRate==null?'—':`%${Math.round(x.hitRate*100)} (${x.correct}/${x.total})`;const confidence=x=>{const h=x?.highConfidence;if(!h||!h.total)return 'Henüz yeterli güvenli tahmin yok';return `≥%${Math.round(h.threshold*100)} güven: %${Math.round(h.rate*100)} (${h.correct}/${h.total}) · kapsam %${Math.round(h.coverage*100)}`};const score=x=>x?.brier==null?'Brier — · LogLoss —':`Brier ${Number(x.brier).toFixed(3)} · LogLoss ${Number(x.logLoss).toFixed(3)}`;return `<div class="card"><b>Yeni motor: aynı maçlarda ileriye dönük karşılaştırma</b><p class="muted">${n?`${n} maç sonucu · maç öncesi dondurulan tahminler`:'Ölçüm, bu sürümle kaydedilecek yeni maçlar sonuçlandıkça başlayacak.'}</p><div class="stats"><div><small>Mevcut Poisson</small><b>${value(models.baseline)}</b><small>${score(models.baseline)}</small><small>${confidence(models.baseline)}</small></div><div><small>Poisson + Elo</small><b>${value(models.elo)}</b><small>${score(models.elo)}</small><small>${confidence(models.elo)}</small></div></div><p class="note">Yüksek güven oranı yalnızca en yüksek 1-X-2 olasılığı en az %60 olan maçları kapsar; kapsam yüzdesi yanında gösterilir. Tahminler aynı maçlarda kıyaslanır. Örnek sayısı büyümeden sonuç kesin kabul edilmez.</p></div>`}
function settings(){let v=state.validation;let rate=v?.primaryHitRate==null?'Henüz sonuç yok':'%'+Math.round(v.primaryHitRate*100);return `<h1 class="heading">Ayarlar</h1><div class="card"><b>Geçmiş tahminlerin başarısı</b><p class="muted">Maç başlamadan önce kaydedilmiş, sonradan sonuçlanmış ${v?.evaluatedPrimaryPredictions||0} maçta tek bir önceden seçilmiş tahmin: <strong>${rate}</strong></p><p class="note">Bu oran geçmiş sonuçları gösterir; gelecek maçlar için başarı garantisi değildir. Yeterli örnek birikene kadar dikkatli yorumlanmalıdır.</p></div>${modelComparisonCard()}<div class="card"><div><b>Günlük veri kontrolü</b><div class="muted">GitHub Actions ile günlük fikstür ve sonuç kontrolü; geçmiş kayıtlar korunur. Canlı maçlar ayrı sorgulanır.</div></div></div><div class="card"><b>Son veri güncellemesi</b><p class="muted">${state.updated?new Date(state.updated).toLocaleString('tr-TR'):'Henüz başarılı güncelleme yok'}</p><button class="iconbtn" id="manual">Şimdi yenile ↻</button></div><div class="card"><b>Veri kaynağı</b><p class="muted">GitHub Actions tarafından hazırlanan data.json dosyası. Kaynak: ESPN kamuya açık futbol skorları uç noktaları (resmî üçüncü taraf API garantisi yoktur).</p></div><p class="note">Canlı skorlar uygulama açıkken veri kaynağından yaklaşık 60 saniyede bir sorgulanır; erişim engellenirse son yayınlanan skor korunur; telefon bildirimleri bu sürümde yoktur. Yerel favoriler bu cihazın tarayıcısında saklanır.</p>`}

function archiveOutcome(k,h,a){const t=h+a;const f={home:h>a,draw:h===a,away:h<a,homeOrDraw:h>=a,noDraw:h!==a,awayOrDraw:h<=a,over15:t>=2,under15:t<=1,over25:t>=3,under25:t<=2,over35:t>=4,under35:t<=3,btts:h>0&&a>0,noBtts:h===0||a===0,homeOver05:h>=1,homeUnder05:h===0,awayOver05:a>=1,awayUnder05:a===0,homeOver15:h>=2,homeOver25:h>=3,awayOver15:a>=2,awayOver25:a>=3,homeUnder15:h<=1,awayUnder15:a<=1,odd:t%2===1,even:t%2===0,over05:t>=1,under05:t===0,over45:t>=5,under45:t<=4,over55:t>=6,under55:t<=5,homeOver15:h>=2,awayOver15:a>=2,homeUnder25:h<=2,awayUnder25:a<=2,goals01:t<=1,goals23:t>=2&&t<=3,goals45:t>=4&&t<=5,goals6plus:t>=6,marginHome1:h-a===1,marginHome2:h-a===2,marginHome3plus:h-a>=3,marginAway1:a-h===1,marginAway2:a-h===2,marginAway3plus:a-h>=3,homeOver15Win:h>a&&t>=2,homeOver25Win:h>a&&t>=3,awayOver15Win:a>h&&t>=2,awayOver25Win:a>h&&t>=3,homeWinBtts:h>a&&a>0,awayWinBtts:a>h&&h>0,over25Btts:t>=3&&h>0&&a>0,under25Btts:t<=2&&h>0&&a>0};return f[k]}
function accuracyStats(filter){let correct=0,total=0;for(const r of state.archive||[]){if(!r?.settled||!Array.isArray(r.score)||!r.p)continue;const h=Number(r.score[0]),a=Number(r.score[1]);if(!Number.isInteger(h)||!Number.isInteger(a))continue;if(filter==='result'){const keys=['home','draw','away'].filter(k=>Number.isFinite(r.p[k]));if(!keys.length)continue;const pick=keys.reduce((best,k)=>r.p[k]>r.p[best]?k:best,keys[0]);correct+=Number(archiveOutcome(pick,h,a)===true);total++;continue}for(const [,options] of markets.slice(1)){const available=options.filter(([,k])=>Number.isFinite(r.p[k]));if(!available.length)continue;const selected=available.reduce((best,row)=>r.p[row[1]]>r.p[best[1]]?row:best,available[0]);correct+=Number(archiveOutcome(selected[1],h,a)===true);total++}}return {correct,total,rate:total?correct/total:null}}
function accuracyCard(){const filter=state.accuracyFilter||'result',s=accuracyStats(filter),label=filter==='result'?'Maç sonuçları (1-X-2)':'Diğer tahmin pazarları';return `<section class="accuracy-card"><div><h2>Tahmin Başarı Oranı</h2><strong class="accuracy-value">${s.rate===null?'—':Math.round(s.rate*100)+'%'}</strong><div class="muted">${s.correct} başarılı / ${s.total} tahmin · ${label}</div></div><div class="accuracy-controls"><button data-accuracy-filter="result" class="${filter==='result'?'active':''}">Maç sonuçları</button><button data-accuracy-filter="markets" class="${filter==='markets'?'active':''}">Diğer tahminler</button></div><small class="muted">Bu arşivdeki geçmiş tahminlerdir. Yeni Poisson + Elo motorunun aynı maçlardaki ileriye dönük kıyası Ayarlar’da ayrı gösterilir; oyuncu motorlarının kıyası bu ölçüme dahil değildir.</small></section>`}
// Mark only the model's preferred outcome in each comparable market.
// Other alternatives stay neutral instead of being marked as failed predictions.
function archivePick(k,p){
  const groups=[['home','draw','away'],['homeOrDraw','noDraw','awayOrDraw'],['over15','under15'],['over25','under25'],['over35','under35'],['btts','noBtts'],['odd','even']];
  const g=groups.find(x=>x.includes(k));
  if(g){const valid=g.filter(x=>Number.isFinite(p?.[x]));if(!valid.length)return false;return valid.reduce((best,x)=>p[x]>p[best]?x:best,valid[0])===k;}
  // Team-goal propositions are separate events, not mutually exclusive alternatives.
  return Number.isFinite(p?.[k])&&p[k]>=.5;
}
function archiveMarketRow(name,k,p,h,a){const selected=archivePick(k,p);const hit=selected?archiveOutcome(k,h,a):null;const bg=!selected?'':`background:${hit?'rgba(0,175,100,.18)':'rgba(220,65,76,.19)'};border-left:4px solid ${hit?'#2bd78c':'#ff6570'};`;const color=!selected?'':`color:${hit?'#6cf0ae':'#ff939d'};`;return `<div class="marketrow" style="${bg}padding:12px;border-radius:9px;margin:7px 0"><div><b>${esc(name)}</b></div><strong style="${color}">%${percent(p[k])}${selected?` · <span aria-label="${hit?'Tahmin gerçekleşti':'Tahmin gerçekleşmedi'}" title="${hit?'Tahmin gerçekleşti':'Tahmin gerçekleşmedi'}">${hit?'✓':'✗'}</span>`:''}</strong></div>`}
function archiveRows(row,m){const h=Number(row.score?.[0]??m?.home?.score),a=Number(row.score?.[1]??m?.away?.score);if(!Number.isInteger(h)||!Number.isInteger(a))return '<div class="muted">Kesin skor bekleniyor.</div>';return markets.map(([group,items])=>`<section class="market"><h3>${esc(group)}</h3>${items.filter(([,k])=>Number.isFinite(row.p?.[k])).map(([name,k])=>archiveMarketRow(name,k,row.p,h,a)).join('')}</section>`).join('')}
function archivePage(){const all=state.archive.filter(r=>r.settled&&r.p&&Array.isArray(r.score)).sort((a,b)=>new Date(b.kickoff)-new Date(a.kickoff));const rows=all.filter(r=>state.league==='all'||r.league===state.league);return `<h1 class="heading">Tahmin Arşivi</h1><p class="muted">Yalnızca maç başlamadan önce kaydedilen tahminler değerlendirilir. Yüksek olasılıklı tahminlerde yeşil ✓, kırmızı ✗ kullanılır; diğer seçenekler işaretsizdir.</p>${leagueTabs()}<div class="muted" style="margin:12px 0">${rows.length} sonuçlanmış ve önceden tahmin edilmiş maç</div>${rows.length?rows.map(r=>{const m=state.history.find(x=>x.id===r.matchId);return `<button class="card match" data-archive-open="${esc(r.matchId)}"><div class="teams"><small>${esc(leagueName(r.league))} · ${fmt(r.kickoff)}</small><b>${esc(m?.home?.name||r.home||'Ev sahibi')} – ${esc(m?.away?.name||r.away||'Deplasman')}</b></div><strong>${r.score[0]} - ${r.score[1]}</strong><span>›</span></button>`}).join(''):'<div class="empty">Henüz sonuçlanmış ve önceden kaydedilmiş tahmin yok. Yeni maçlar tamamlandıkça burada görünecek.</div>'}`}
function archiveDetail(){const r=state.archive.find(x=>x.matchId===state.match&&x.settled);if(!r)return '<div class="empty">Arşiv kaydı bulunamadı.</div>';const m=state.history.find(x=>x.id===r.matchId);return `<button class="link" data-page="archive">‹ Arşive dön</button><h1 class="heading">Maç Sonucu ve Tahmin Kontrolü</h1><div class="detailhero"><div class="muted" style="text-align:center">${esc(leagueName(r.league))} · ${fmt(r.kickoff)} · Maç tamamlandı</div><div class="versus"><div>${m?logo(m.home):''}<b>${esc(m?.home?.name||r.home||'Ev sahibi')}</b></div><strong>${r.score[0]} - ${r.score[1]}</strong><div>${m?logo(m.away):''}<b>${esc(m?.away?.name||r.away||'Deplasman')}</b></div></div></div><h2>Maç Sonucu Tahmini (1-X-2)</h2><section class="market">${markets[0][1].filter(([,k])=>Number.isFinite(r.p[k])).map(([name,k])=>archiveMarketRow(name,k,r.p,r.score[0],r.score[1])).join('')}</section><h2>Diğer tahminlerin sonuçları</h2>${markets.slice(1).map(([group,items])=>`<section class="market"><h3>${esc(group)}</h3>${items.filter(([,k])=>Number.isFinite(r.p[k])).map(([name,k])=>archiveMarketRow(name,k,r.p,r.score[0],r.score[1])).join('')}</section>`).join('')}<p class="note">Yalnızca yüksek olasılıklı tercih işaretlenir: yeşil ✓ gerçekleşti, kırmızı ✗ gerçekleşmedi. Diğer seçenekler karşılaştırma için işaretsiz gösterilir. Yüzdeler maç öncesinde kaydedilmiştir.</p>`}
function ensureArchiveNav(){const nav=document.querySelector('nav');if(!nav||nav.querySelector('[data-page="archive"]'))return;const b=document.createElement('button');b.dataset.page='archive';b.innerHTML='▤<span>Arşiv</span>';const settings=nav.querySelector('[data-page="settings"]');nav.insertBefore(b,settings||null);nav.style.display='grid';nav.style.gridTemplateColumns='repeat(6,minmax(0,1fr))';nav.querySelectorAll('button').forEach(x=>{x.style.minWidth='0';x.style.paddingLeft='2px';x.style.paddingRight='2px';});}

const mlV45={mode:['classic','ml','player-poisson','player-ml'].includes(localStorage.getItem('ml-v45-mode'))?localStorage.getItem('ml-v45-mode'):'classic',predictions:{},history:[]};
function mlV45Prediction(matchId){const item=mlV45.predictions?.[matchId],p=item?.p||item;if(!p)return null;const q={home:Number(p.home),draw:Number(p.draw),away:Number(p.away)};return Object.values(q).every(Number.isFinite)&&Object.values(q).every(x=>x>=0&&x<=1)?q:null}
function playerAvailabilityWeight(raw){const s=String(raw||'unknown').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/out|injur|suspend|unavailable|sidelined|ruled out|not available|sakat|cezali/.test(s))return 0;if(/doubtful|questionable|fitness test|late test|day.to.day|supheli|durumu belirsiz/.test(s))return .5;if(/available|fit|healthy|probable|oynayabilir|saglikli/.test(s))return 1;return null}
function playerTeamStats(m,side){const teams=state.playerFeatures?.teams||{};const id=String(m?.[side]?.id||'');const t=teams[`${m.league}:${id}`];if(!t||!Array.isArray(t.players)||t.players.length<5)return null;const kickoff=Date.parse(m.date),generated=Date.parse(state.playerFeatures.generatedAt),roster=Date.parse(t.rosterAsOf);if(!Number.isFinite(kickoff)||!Number.isFinite(generated)||!Number.isFinite(roster)||generated>=kickoff||roster>=kickoff)return null;let apps=0,goals=0,shots=0,onTarget=0,known=0,availabilityKnown=0,unavailablePlayers=[],doubtfulPlayers=[];for(const p of t.players){const as=typeof p?.appearances==='number'?p.appearances:NaN,g=typeof p?.goals==='number'?p.goals:NaN;if(!Number.isFinite(as)||as<0)continue;if(Number.isFinite(g)&&g>=0){const at=Date.parse(p.seasonStatsAsOf);if(!Number.isFinite(at)||at>=kickoff)continue;known++;const weight=playerAvailabilityWeight(p.availability);if(weight!==null)availabilityKnown++;if(weight===0)unavailablePlayers.push(p.name);if(weight===.5)doubtfulPlayers.push(p.name);const effectiveWeight=weight===null?1:weight;apps+=as*effectiveWeight;goals+=g*effectiveWeight;const sh=typeof p.shots==='number'?p.shots:NaN,sot=typeof p.shotsOnTarget==='number'?p.shotsOnTarget:NaN;if(Number.isFinite(sh)&&sh>=0)shots+=sh*effectiveWeight;if(Number.isFinite(sot)&&sot>=0)onTarget+=sot*effectiveWeight;}}const coverage=known/t.players.length;if(coverage<.7||apps<10)return null;return {goals,apps,shots,onTarget,coverage,availabilityCoverage:known?availabilityKnown/known:0,availabilityKnown,availabilitySample:known,unavailablePlayers,doubtfulPlayers,seasonYear:t.seasonYear,seasonStatus:t.seasonStatus};}
function playerAttackRate(s){if(!s)return null;return Math.max(.15,Math.min(4.5,11*(s.goals+.08*s.onTarget+.015*s.shots)/Math.max(10,s.apps)))}
function playerPoisson(m,a){const h=playerTeamStats(m,'home'),v=playerTeamStats(m,'away'),rh=playerAttackRate(h),ra=playerAttackRate(v);if(rh===null||ra===null||!Number.isFinite(a?.lh)||!Number.isFinite(a?.la))return null;const lh=Math.max(.15,Math.min(4.5,.55*a.lh+.45*rh)),la=Math.max(.15,Math.min(4.5,.55*a.la+.45*ra));let home=0,draw=0,away=0,total=0;for(let i=0;i<=15;i++)for(let j=0;j<=15;j++){const w=pois(i,lh)*pois(j,la);total+=w;if(i>j)home+=w;else if(i===j)draw+=w;else away+=w}if(!total)return null;return {home:home/total,draw:draw/total,away:away/total,lh,la,features:{home:h,away:v}}}
function playerBlend(base,player){const raw={home:.55*base.home+.45*player.home,draw:.55*base.draw+.45*player.draw,away:.55*base.away+.45*player.away};const sum=raw.home+raw.draw+raw.away;return {home:raw.home/sum,draw:raw.draw/sum,away:raw.away/sum}}
function mlV45Apply(m,a){if(m.done||!a?.ready)return a;if(mlV45.mode==='ml'){const p=mlV45Prediction(m.id);return p?{...a,p:{...a.p,...p,homeOrDraw:p.home+p.draw,awayOrDraw:p.away+p.draw,noDraw:p.home+p.away},model:'Machine Learning (1X2)',mlExperimental:true}:a}if(mlV45.mode==='player-poisson'||mlV45.mode==='player-ml'){const pp=playerPoisson(m,a);if(!pp)return {...a,ready:false,playerUnavailable:true};let p,modelName;if(mlV45.mode==='player-poisson'){p={home:pp.home,draw:pp.draw,away:pp.away};modelName='Oyuncu verili Poisson (deneysel)'}else{const mlBase=mlV45Prediction(m.id);if(!mlBase)return {...a,ready:false,playerUnavailable:true,playerMLUnavailable:true};p=playerBlend(mlBase,pp);modelName='Oyuncu verili ML (deneysel harman)'}return {...a,p:{...a.p,...p,homeOrDraw:p.home+p.draw,awayOrDraw:p.away+p.draw,noDraw:p.home+p.away},model:modelName,playerModel:true,playerFeatures:pp.features,playerLambda:{home:pp.lh,away:pp.la}}}return a}

function mlV45Comparison(){const baseline=new Map((state.archive||[]).filter(x=>x?.settled&&Array.isArray(x.score)&&x.p).map(x=>[String(x.matchId),x]));const common=(mlV45.history||[]).filter(x=>x?.settled&&Array.isArray(x.score)&&x.p&&baseline.has(String(x.id))).filter(x=>{const b=baseline.get(String(x.id));return Number(b.score[0])===Number(x.score[0])&&Number(b.score[1])===Number(x.score[1])});const summary=(rows,prob)=>{let correct=0,brier=0,n=0;for(const row of rows){const p=prob(row);const score=row.score||[];if(!p||!Number.isInteger(Number(score[0]))||!Number.isInteger(Number(score[1])))continue;const actual=Number(score[0])>Number(score[1])?0:Number(score[0])===Number(score[1])?1:2,values=[Number(p.home),Number(p.draw),Number(p.away)];if(!values.every(Number.isFinite))continue;correct+=Number(values.indexOf(Math.max(...values))===actual);brier+=values.reduce((sum,v,i)=>sum+(v-(i===actual?1:0))**2,0);n++}return n?`${Math.round(correct/n*100)}% doğruluk · Brier ${ (brier/n).toFixed(3) }`:'ölçüm bekleniyor'};const baseRows=common.map(x=>baseline.get(String(x.id)));return `<small style="flex-basis:100%;color:#b8c9d8">Aynı tamamlanmış maçlarda (${common.length}): Mevcut sistem ${esc(summary(baseRows,x=>x.p))} · ML ${esc(summary(common,x=>x.p))}</small>`}
function mlV45Switch(){const classic=mlV45.mode==='classic',ml=mlV45.mode==='ml',playerPoisson=mlV45.mode==='player-poisson',playerML=mlV45.mode==='player-ml';return `<section class="model-switch" aria-label="Tahmin modeli seçimi"><b>Tahmin motoru</b><button type="button" data-ml-mode="classic" aria-pressed="${classic}" class="${classic?'active':''}">Mevcut sistem</button><button type="button" data-ml-mode="ml" aria-pressed="${ml}" class="${ml?'active':''}">Machine Learning</button><button type="button" data-ml-mode="player-poisson" aria-pressed="${playerPoisson}" class="${playerPoisson?'active':''}">Oyuncu verili Poisson</button><button type="button" data-ml-mode="player-ml" aria-pressed="${playerML}" class="${playerML?'active':''}">Oyuncu verili ML</button><small>${playerPoisson?'Poisson / Elo tahmini, maç öncesi oyuncu sezon verileriyle harmanlanır.':playerML?'Mevcut ML 1-X-2 tahmini oyuncu verili Poisson çıktısıyla deneysel olarak harmanlanır.':'Mevcut: Poisson / Elo · ML: ayrı 1-X-2 modeli'}</small>${mlV45Comparison()}</section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ml-mode]');if(!b)return;mlV45.mode=b.dataset.mlMode;localStorage.setItem('ml-v45-mode',mlV45.mode);render()});
async function mlV45Load(){try{const r=await fetch('./ml_predictions.json?ts='+Date.now(),{cache:'no-store'});if(r.ok){const j=await r.json();mlV45.predictions=j.predictions||{};mlV45.history=Array.isArray(j.history)?j.history:[]}}catch(e){console.warn('Experimental ML predictions unavailable',e)}try{const cached=state.playerFeatures;const response=await fetch('https://raw.githubusercontent.com/yildizatakan-bit/skor/feature/ml-comparison-20261027/player_team_features.json?ts='+Date.now(),{cache:'no-store'});if(response.ok){const feed=await response.json();if(feed?.teams&&feed?.generatedAt){state.playerFeatures=feed;save('playerFeatures',feed)}}else if(!cached)state.playerFeatures=null}catch(e){console.warn('Player statistics feed unavailable',e)}render()}
function render(){ensureArchiveNav();let navPage=state.page==='detail'?'matches':state.page==='archiveDetail'?'archive':state.page;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===navPage));$('content').innerHTML=({home,matches,leagues,favorites,settings,detail,archive:archivePage,archiveDetail}[state.page]||home)();if(['home','matches','detail','favorites'].includes(state.page))$('content').insertAdjacentHTML('afterbegin',mlV45Switch());if(state.failures.length&&state.page==='settings')$('content').insertAdjacentHTML('beforeend',`<div class="banner">Erişim uyarıları: ${esc(state.failures.join(' | '))}</div>`)}
async function load(force=false){
  if(state.loading)return;
  state.loading=true;state.failures=[];render();
  // Preferred path: data.json is refreshed by GitHub Actions approximately every 5 minutes.
  // Manual refresh reloads the published snapshot; it does not silently scrape other sites.
  try{
    const r=await fetch('./data.json?ts='+Date.now(),{cache:'no-store'});
    if(!r.ok)throw Error('HTTP '+r.status);
    const j=await r.json();
    if(!Array.isArray(j.events)||!j.events.length)throw Error('Boş veri dosyası');
    const valid=j.events.filter(x=>x&&x.id&&x.league&&x.date&&x.home&&x.away);
    if(!valid.length)throw Error('Geçerli maç bulunamadı');
    state.history=valid;
    state.analyses=j.analyses||{};state.validation=j.validation||null;state.modelComparison=j.modelComparison||null;state.archive=Array.isArray(j.predictionArchive)?j.predictionArchive:[];
    const now=Date.now();
    state.fixtures=valid.filter(m=>retainFinished(m,now)||(!m.done&&(m.live||(new Date(m.date).getTime()>=now-4*3600e3&&new Date(m.date).getTime()<=now+7*864e5)))).sort((a,b)=>Number(!!b.live)-Number(!!a.live)||new Date(a.date)-new Date(b.date));
    state.updated=Date.parse(j.updatedAt)||Date.now();
    state.failures=j.errors||[];
    save('updated',state.updated);save('events',valid);save('analyses',state.analyses);
  }catch(err){
    state.failures=['Yayınlanan veri dosyasına ulaşılamadı: '+err.message];
    // Do not delete last valid cached snapshot.
    if(!state.history?.length){const cached=read('events',[]);if(Array.isArray(cached)&&cached.length){state.history=cached;state.analyses=read('analyses',{});state.fixtures=cached.filter(m=>!m.done||retainFinished(m));}}
  }
  state.loading=false;render();pollLive();
}
// Historical results are kept in a separate collection, so past matches are never lost when the fixture list is built.
function fixtureWithHistory(m){
  // The backend has the authoritative v14 Elo + Poisson result. Do not
  // silently replace it with the old browser-only goals-average model.
  const stored=state.analyses?.[m.id];
  const base=stored || {ready:false,nh:0,na:0};
  const frozen=state.archive?.find(x=>x.matchId===m.id);
  const historical=frozen?.p && base.ready?{...base,p:frozen.p}:base;
  return {...m,analysis:mlV45Apply(m,historical)};
}
fixture=fixtureWithHistory;
function init(){state.history=[];state.analyses={};state.fixtures=[];render();load();mlV45Load()}
document.addEventListener('change',e=>{if(e.target.id==='match-filter-group'){state.listGroup=e.target.value;state.listMarket='all';render()}else if(e.target.id==='match-filter-choice'){state.listMarket=e.target.value;render()}});
document.addEventListener('click',e=>{let el=e.target.closest('button');if(!el){const slide=e.target.closest('#featured-slide[data-open]');if(slide){state.match=slide.dataset.open;state.market='all';state.page='detail';render();scrollTo(0,0)}return}let d=el.dataset;if(d.accuracyFilter){state.accuracyFilter=d.accuracyFilter;render()}else if(d.page){state.page=d.page;state.market='all';render();scrollTo(0,0)}else if(d.league!==undefined){state.league=d.league;state.slide=0;render()}else if(d.leaguepage){state.league=d.leaguepage;state.page='matches';render()}else if(d.archiveOpen){state.match=d.archiveOpen;state.page='archiveDetail';render();scrollTo(0,0)}else if(d.open){state.match=d.open;state.market='all';state.page='detail';render();scrollTo(0,0)}else if(d.market){state.market=d.market;render()}else if(d.slide){state.slide+=d.slide==='next'?1:-1;let n=featuredMatches().length;state.slide=(state.slide+n)%Math.max(n,1);render()}else if(d.fav){let [matchId,k]=d.fav.split('|'),index=state.favs.findIndex(x=>x.id===d.fav);if(index>=0)state.favs.splice(index,1);else{let m=state.fixtures.find(x=>x.id===matchId),a=m&&fixture(m).analysis,found=markets.flatMap(([group,rows])=>rows.map(([name,market])=>({group,name,market}))).find(x=>x.market===k);if(!m||!a.ready||!found||!Number.isFinite(a.p[k])||a.p[k]<.5)return;state.favs.push({id:d.fav,matchId,market:k,group:found.group,name:found.name,home:m.home.name,away:m.away.name,date:m.date,p:a.p[k]})}save('favorites',state.favs);render()}else if(el.id==='manual'||el.id==='refresh'){load(true)}});
document.addEventListener('change',e=>{if(e.target.id==='auto'){state.settings.auto=e.target.checked;save('settings',state.settings);render()}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});init();

// Keep historical analysis in the GitHub snapshot; poll only today's scoreboard for live scores.
// ESPN's unofficial endpoint may disallow browser CORS; in that case the published snapshot remains.
let livePolling=false;
async function pollLive(){
  if(document.hidden||livePolling)return;
  livePolling=true;
  try{
    const today=new Date(),yesterday=new Date(today.getTime()-86400000);
    const tomorrow=new Date(today.getTime()+86400000);const dates=[dateKey(yesterday),dateKey(tomorrow)];
    const updates=await Promise.allSettled(LEAGUES.map(async ([league])=>{
      const url=BASE+encodeURIComponent(league)+'/scoreboard?dates='+dates.join('-')+'&limit=200';
      const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),9000);
      try{
        const response=await fetch(url,{cache:'no-store',signal:ctl.signal});
        if(!response.ok)throw Error('HTTP '+response.status);
        const payload=await response.json();
        return (payload.events||[]).map(e=>{
          const comp=e.competitions?.[0],home=comp?.competitors?.find(x=>x.homeAway==='home'),away=comp?.competitors?.find(x=>x.homeAway==='away');
          const type=e.status?.type||{},live=type.state==='in'&&!type.completed;
          const done=type.completed===true;
          if(!home||!away)return null;
          const score=x=>x?.score!==undefined&&x.score!==null&&String(x.score).trim()!==''&&Number.isFinite(Number(x.score))?Number(x.score):null;
          return {id:league+':'+e.id,live,done,clock:String(e.status?.displayClock||''),hs:score(home),as:score(away),event:parseEvent(e,league)};
        }).filter(Boolean);
      }finally{clearTimeout(timer)}
    }));
    const map=new Map(updates.filter(x=>x.status==='fulfilled').flatMap(x=>x.value).map(x=>[x.id,x]));
    let changed=false;
    for(const v of map.values()){
      if(!v.live||!v.event||state.fixtures.some(m=>m.id===v.id))continue;
      const m={...v.event,live:true,clock:v.clock,done:false};
      m.home.score=v.hs;m.away.score=v.as;
      state.fixtures.push(m);
      if(!state.history.some(x=>x.id===m.id))state.history.push(m);
      changed=true;
    }
    for(const m of state.fixtures){
      const v=map.get(m.id);if(!v)continue;
      const newLive=v.live,clock=v.clock,hs=(v.live||v.done)?v.hs:null,as=(v.live||v.done)?v.as:null;
      if(m.live!==newLive||m.clock!==clock||m.home.score!==hs||m.away.score!==as){
        m.live=newLive;m.clock=clock;m.home.score=hs;m.away.score=as;changed=true;
      }
      if(v.done){if(!m.done)recordFinished(m);m.done=true;m.live=false;changed=true}
    }
    if(changed){state.fixtures=state.fixtures.filter(m=>!m.done||retainFinished(m)).sort((a,b)=>Number(!!b.live)-Number(!!a.live)||new Date(a.date)-new Date(b.date));render();}
  }catch(e){/* Preserve the last published snapshot when the live source is unavailable. */}
  finally{livePolling=false}
}
setInterval(()=>{if(!document.hidden){state.fixtures=state.fixtures.filter(m=>!m.done||retainFinished(m));pollLive();render()}},60*1000);
setInterval(()=>{if(!document.hidden)load()},5*60*1000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden){pollLive();if(!state.updated||Date.now()-state.updated>5*60*1000)load()}});

// Advance the featured carousel only while the home page is visible.
// Manual swipes remain available, and a single featured match stays still.
setInterval(()=>{if(document.hidden||state.page!=='home')return;const count=featuredMatches().length;if(count<2)return;state.slide=(state.slide+1)%count;render()},5000);

// Swipe between featured matches on touch screens.
let touchStartX=null;document.addEventListener('touchstart',e=>{if(e.target.closest('#featured-slide'))touchStartX=e.changedTouches[0].screenX},{passive:true});document.addEventListener('touchend',e=>{if(touchStartX===null)return;const delta=e.changedTouches[0].screenX-touchStartX;touchStartX=null;if(Math.abs(delta)<45||state.page!=='home'||featuredMatches().length<2)return;state.slide+=delta<0?1:-1;render()},{passive:true});

// Keyboard support for the clickable featured match.
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('#featured-slide[data-open]')){e.preventDefault();state.match=e.target.dataset.open;state.market='all';state.page='detail';render();scrollTo(0,0)}});
